void mainImage( out vec4 O, vec2 U )
{
    ivec2 I = ivec2(-U.x, U.y); // only looking at -a/+b quadrant

    int x = abs(I.x) % (I.y);
    int y = (-I.x) % (I.y);     // since I.x is always negative, -I.x should be equal to abs(I.x)

    O = x == y ? vec4(0, 1, 0, 1) : vec4(1, 0, 0, 1);
}
